<template>
  <view class="patient-list">
    <view class="header">
      <view class="nav-bar">
        <view class="back-btn" @click="goBack">
          <text class="back-icon">&#xe60e;</text>
          <text>返回</text>
        </view>
        <text class="title">患者列表</text>
      </view>
      <view class="date-selector">
        <view 
          v-for="(day, index) in weekDays" 
          :key="index" 
          class="date-item" 
          :class="{ active: currentDateIndex === index }"
          @click="selectDate(index)"
        >
          <text class="day">{{ day.dayOfWeek }}</text>
          <text class="date">{{ day.date }}</text>
        </view>
      </view>
    </view>
    
    <view class="time-filter">
      <view 
        v-for="(slot, index) in timeSlots" 
        :key="index"
        class="time-slot"
        :class="{ active: currentTimeSlot === slot }"
        @click="selectTimeSlot(slot)"
      >
        {{ slot }}
      </view>
    </view>
    
    <view class="patient-container">
      <view v-if="patients.length === 0" class="empty-tip">
        <text>当前时段无患者</text>
      </view>
      <view v-else v-for="(patient, index) in patients" :key="index" class="patient-card" @click="viewPatientDetail(patient)">
        <view class="patient-info">
          <view class="patient-name-time">
            <text class="patient-name">{{ patient.name }}</text>
            <text class="appointment-time">{{ patient.appointmentTime }}</text>
          </view>
          <view class="patient-identity">{{ patient.identity }}</view>
        </view>
        <view class="patient-status" :class="patient.status">
          {{ getStatusText(patient.status) }}
        </view>
      </view>
    </view>
  </view>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { uniNavigateTo } from '@/utils/uniHelper';

// 生成未来7天的日期
const generateWeekDays = () => {
  const days = [];
  const dayNames = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'];
  
  for (let i = 0; i < 7; i++) {
    const date = new Date();
    date.setDate(date.getDate() + i);
    days.push({
      date: `${date.getMonth() + 1}/${date.getDate()}`,
      fullDate: date.toISOString().split('T')[0],
      dayOfWeek: dayNames[date.getDay()]
    });
  }
  return days;
};

const weekDays = ref(generateWeekDays());
const currentDateIndex = ref(0);
const timeSlots = ref(['全部', '上午', '下午']);
const currentTimeSlot = ref('全部');
const patients = ref([]);

// 模拟数据 - 实际应用中应从API获取
const fetchPatients = (dateIndex, timeSlot) => {
  // 模拟API调用
  setTimeout(() => {
    if (dateIndex === 0) {
      let filteredPatients = [
        { 
          id: 1, 
          name: '张三', 
          appointmentTime: '上午 9:00', 
          identity: '学生', 
          status: 'waiting',
          age: 20,
          gender: '男',
          medicalHistory: '无特殊病史',
          previousVisits: [
            { date: '2023-05-15', department: '内科', doctor: '李医生' }
          ]
        },
        { 
          id: 2, 
          name: '李四', 
          appointmentTime: '上午 10:30', 
          identity: '教职工', 
          status: 'in-progress',
          age: 45,
          gender: '女',
          medicalHistory: '高血压',
          previousVisits: [
            { date: '2023-04-20', department: '内科', doctor: '李医生' },
            { date: '2023-03-10', department: '心内科', doctor: '王医生' }
          ]
        },
        { 
          id: 3, 
          name: '王五', 
          appointmentTime: '下午 14:30', 
          identity: '学生', 
          status: 'waiting',
          age: 22,
          gender: '男',
          medicalHistory: '过敏体质',
          previousVisits: []
        },
        { 
          id: 4, 
          name: '赵六', 
          appointmentTime: '下午 15:45', 
          identity: '教职工', 
          status: 'completed',
          age: 50,
          gender: '男',
          medicalHistory: '糖尿病',
          previousVisits: [
            { date: '2023-05-05', department: '内分泌科', doctor: '张医生' }
          ]
        }
      ];
      
      if (timeSlot === '上午') {
        filteredPatients = filteredPatients.filter(p => p.appointmentTime.includes('上午'));
      } else if (timeSlot === '下午') {
        filteredPatients = filteredPatients.filter(p => p.appointmentTime.includes('下午'));
      }
      
      patients.value = filteredPatients;
    } else if (dateIndex === 1) {
      let filteredPatients = [
        { 
          id: 5, 
          name: '钱七', 
          appointmentTime: '上午 9:15', 
          identity: '学生', 
          status: 'waiting',
          age: 19,
          gender: '女',
          medicalHistory: '无',
          previousVisits: []
        },
        { 
          id: 6, 
          name: '孙八', 
          appointmentTime: '下午 16:00', 
          identity: '教职工', 
          status: 'waiting',
          age: 35,
          gender: '男',
          medicalHistory: '胃炎',
          previousVisits: [
            { date: '2023-02-15', department: '消化内科', doctor: '刘医生' }
          ]
        }
      ];
      
      if (timeSlot === '上午') {
        filteredPatients = filteredPatients.filter(p => p.appointmentTime.includes('上午'));
      } else if (timeSlot === '下午') {
        filteredPatients = filteredPatients.filter(p => p.appointmentTime.includes('下午'));
      }
      
      patients.value = filteredPatients;
    } else {
      patients.value = [];
    }
  }, 300);
};

const selectDate = (index) => {
  currentDateIndex.value = index;
  fetchPatients(index, currentTimeSlot.value);
};

const selectTimeSlot = (slot) => {
  currentTimeSlot.value = slot;
  fetchPatients(currentDateIndex.value, slot);
};

const getStatusText = (status) => {
  switch (status) {
    case 'waiting': return '待接诊';
    case 'in-progress': return '接诊中';
    case 'completed': return '已完成';
    default: return '未知';
  }
};

const viewPatientDetail = (patient) => {
  // 将患者信息序列化为URL参数
  const patientInfo = encodeURIComponent(JSON.stringify(patient));
  uniNavigateTo({ url: `/pages/doctor/patients/patient-detail?patient=${patientInfo}` });
};

const goBack = () => {
  uniNavigateTo({ url: '/pages/doctor/schedule/schedule' });
};

onMounted(() => {
  fetchPatients(0, '全部');
});
</script>

<style scoped>
.patient-list {
  min-height: 100vh;
  background-color: #f5f7fa;
}

.header {
  background-color: #1677ff;
  padding: 0 0 20rpx 0;
  color: #fff;
}

.nav-bar {
  position: relative;
  height: 90rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 30rpx;
}

.back-btn {
  position: absolute;
  left: 30rpx;
  display: flex;
  align-items: center;
  font-size: 28rpx;
}

.back-icon {
  font-family: "iconfont";
  margin-right: 6rpx;
}

.title {
  font-size: 36rpx;
  font-weight: bold;
}

.date-selector {
  display: flex;
  overflow-x: auto;
  padding: 0 30rpx 10rpx 30rpx;
}

.date-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 30rpx;
  padding: 16rpx 24rpx;
  border-radius: 12rpx;
  background-color: rgba(255, 255, 255, 0.2);
}

.date-item.active {
  background-color: #fff;
}

.date-item.active .day,
.date-item.active .date {
  color: #1677ff;
}

.day {
  font-size: 24rpx;
  margin-bottom: 6rpx;
}

.date {
  font-size: 28rpx;
  font-weight: 500;
}

.time-filter {
  display: flex;
  padding: 20rpx 30rpx;
  background-color: #fff;
  border-bottom: 2rpx solid #eee;
}

.time-slot {
  padding: 10rpx 30rpx;
  margin-right: 20rpx;
  border-radius: 30rpx;
  font-size: 26rpx;
  color: #666;
  background-color: #f5f7fa;
}

.time-slot.active {
  background-color: #1677ff;
  color: #fff;
}

.patient-container {
  padding: 30rpx;
}

.empty-tip {
  text-align: center;
  padding: 100rpx 0;
  color: #999;
  font-size: 28rpx;
}

.patient-card {
  background-color: #fff;
  border-radius: 16rpx;
  padding: 30rpx;
  margin-bottom: 20rpx;
  box-shadow: 0 2rpx 10rpx rgba(0, 0, 0, 0.05);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.patient-info {
  flex: 1;
}

.patient-name-time {
  display: flex;
  align-items: center;
  margin-bottom: 10rpx;
}

.patient-name {
  font-size: 32rpx;
  font-weight: bold;
  color: #333;
  margin-right: 20rpx;
}

.appointment-time {
  font-size: 26rpx;
  color: #666;
}

.patient-identity {
  font-size: 26rpx;
  color: #999;
}

.patient-status {
  width: 120rpx;
  height: 60rpx;
  border-radius: 30rpx;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26rpx;
}

.patient-status.waiting {
  background-color: #e6f7ff;
  color: #1677ff;
}

.patient-status.in-progress {
  background-color: #fff7e6;
  color: #fa8c16;
}

.patient-status.completed {
  background-color: #f6ffed;
  color: #52c41a;
}
</style>